package com.example.optionsmenu; import android.os.Bundle; import android.view.Menu; import android.view.MenuItem; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);} @Override public boolean onCreateOptionsMenu(Menu m){getMenuInflater().inflate(R.menu.menu_main,m);return true;} @Override public boolean onOptionsItemSelected(MenuItem item){int id=item.getItemId();if(id==R.id.menuHome){Toast.makeText(this,"Home Selected",Toast.LENGTH_SHORT).show();return true;}if(id==R.id.menuProfile){Toast.makeText(this,"Profile Selected",Toast.LENGTH_SHORT).show();return true;}if(id==R.id.menuSettings){Toast.makeText(this,"Settings Selected",Toast.LENGTH_SHORT).show();return true;}if(id==R.id.menuAbout){Toast.makeText(this,"About Selected",Toast.LENGTH_SHORT).show();return true;}if(id==R.id.menuExit){finish();return true;}return super.onOptionsItemSelected(item);}}
